export function deploymentDetail(id){const d=deployments.find(x=>x.id===id);if(!d)return notFound();const c=certBy(d.cert);const s=serverBy(d.target);const rolled=d.status==='rolled_back';const recovering=d.status==='needs_attention';const unchanged=d.status==='unchanged';const working=d.status==='running';const steps=[['DatabaseBackup',t('Back up current files','Mevcut dosyaları yedekle'),t('Certificate and key saved to the recovery directory.','Sertifika ve anahtar kurtarma dizinine kaydedildi.')],['FileKey2',t('Write certificate and key','Sertifika ve anahtarı yaz'),t('Atomic file replacement completed.','Dosyalar atomik olarak değiştirildi.')],['CheckCheck',t('Test Nginx configuration','Nginx yapılandırmasını test et'),rolled?t('Configuration validation failed. Automatic recovery started.','Yapılandırma doğrulanamadı. Otomatik kurtarma başladı.'):t('Configuration test passed.','Yapılandırma testi geçti.')],['RefreshCw',t('Reload Nginx','Nginx’i yeniden yükle'),t('Reload requested after the configuration check.','Yapılandırma kontrolünden sonra yeniden yükleme istendi.')],['ShieldCheck',t('Verify TLS endpoint','TLS uç noktasını doğrula'),t('Served fingerprint matches the requested certificate.','Sunulan parmak izi istenen sertifikayla eşleşiyor.')]];
return `<div class="mb16">${navLink(t('All deployments','Tüm dağıtımlar'),'deployments','ArrowLeft')}</div>`+title(t('Deployment','Dağıtım')+' <span class="mono">#'+id.replace('dep-','')+'</span>',`${esc(c.name)} → ${esc(s.name)}`,statusBadge(d.status))+
notice(rolled?t('Previous files restored','Önceki dosyalar geri yüklendi'):recovering?t('Remote outcome is not yet confirmed','Uzak işlem sonucu henüz doğrulanamadı'):unchanged?t('Certificate was already in place','Sertifika zaten yerindeydi'):working?t('Deployment in progress','Dağıtım devam ediyor'):t('Certificate deployed and remotely verified','Sertifika dağıtıldı ve uzaktan doğrulandı'),rolled?t('The Nginx configuration check failed. Alice restored the previous files and verified the previous certificate.','Nginx yapılandırma testi başarısız oldu. Alice önceki dosyaları geri yükledi ve önceki sertifikayı doğruladı.'):recovering?t('Alice is checking the server. Review the changed host identity before allowing further access.','Alice sunucuyu kontrol ediyor. Erişime izin vermeden önce değişen sunucu kimliğini inceleyin.'):working?t('The demo will update this record when verification finishes.','Örnek işlem doğrulama tamamlanınca güncellenecek.'):t('Inspect the steps and fingerprints below for the result of this operation.','Bu işlemin sonucu için aşağıdaki adımları ve parmak izlerini inceleyin.'),rolled||recovering?'warn':'')+
`<div class="detail-grid mt24"><div class="stack">${panel(t('Deployment sequence','Dağıtım adımları'),t('Changes are verified before an operation is marked complete.','İşlem tamamlandı olarak işaretlenmeden önce değişiklikler doğrulanır.'),`<div class="timeline">${steps.map((x,i)=>{const notrun=(rolled&&i>2)||(recovering&&i>1)||unchanged;const stepState=notrun?'':rolled&&i===2?'danger':working&&i>=3?'info':'success';return `<div class="timeline-step"><span class="step-marker ${stepState}">${icon(stepState==='success'?'Check':stepState==='danger'?'X':notrun?'Circle':x[0])}</span><div><h3>${x[1]}</h3><p>${notrun?t('Not run','Çalıştırılmadı'):x[2]}</p></div><time>${notrun?'—':working&&i>=3?'…':(i+1)*1.3+'s'}</time></div>`}).join('')}${rolled?`<div class="timeline-step"><span class="step-marker success">${icon('RotateCw')}</span><div><h3>${t('Restore and verify previous certificate','Önceki sertifikayı geri yükle ve doğrula')}</h3><p>${t('Backup restored · Nginx reloaded · previous endpoint verified.','Yedek geri yüklendi · Nginx yeniden yüklendi · önceki sertifika doğrulandı.')}</p></div><time>7.1s</time></div>`:''}</div>`)}
${panel(t('Operation log','İşlem günlüğü'),t('Illustrative step output · no live connection','Örnek adım çıktısı · canlı bağlantı yok'),panelBody(`<div class="event-log"><p><time>${d.at}</time>[precheck] ${esc(s.name)} :22</p><p><time>+01.200</time>[backup] ${unchanged?'skipped':'saved'}</p>${rolled?'<p class="red"><time>+08.400</time>[config_test] failed</p><p><time>+10.120</time>[restore] previous files restored</p><p class="green"><time>+23.600</time>[verify_old] fingerprint matched</p>':recovering?'<p class="orange"><time>+04.800</time>[recovering] connection unavailable</p>':`<p class="green"><time>+${d.duration}</time>[${unchanged?'unchanged':'verify'}] ${working?'pending':'complete'}</p>`}</div>`))}</div><div class="stack">${panel(t('Operation details','İşlem ayrıntıları'),'',panelBody(`<div class="facts">${fact(t('Certificate','Sertifika'),link(esc(c.name),'certificates/'+c.id,'','text-link'))}${fact(t('Target','Hedef'),link(esc(s.name),'servers/'+s.id,'','text-link'))}${fact(t('Initiated by','Başlatan'),d.by)}${fact(t('Source','Kaynak'),d.trigger==='key_vault'?'Azure Key Vault':t('Manual upload','Manuel yükleme'))}${fact(t('Started','Başlangıç'),'12 Oct 2026 · '+d.at+' UTC')}${fact(t('Verification','Doğrulama'),recovering||working?t('Pending','Bekleniyor'):t('Remote TLS handshake','Uzak TLS el sıkışması'))}${fact(t('Certificate path','Sertifika yolu'),'<code>/etc/nginx/ssl/fullchain.pem</code>')}</div>`))}${panel(t('Evidence','Kanıt'),'',panelBody(`<div class="field"><span class="field-label">${t('Requested fingerprint','İstenen parmak izi')}</span><code>${c.fingerprint.slice(0,47)}…</code></div><div class="field"><span class="field-label">${t('Served fingerprint','Sunulan parmak izi')}</span><code>${recovering||working?t('Not confirmed','Doğrulanmadı'):rolled?'92:4A:11:F8:7D:23:61:8E:31:7D:…':c.fingerprint.slice(0,47)+'…'}</code></div>${canSeeAudit()?navLink(t('Inspect audit record','Denetim kaydını incele'),'audit') : ''}`))}</div></div>${footer()}`}
