function auditTable(events){return table([t('Time / sequence','Zaman / sıra'),t('Actor','İşlemi yapan'),t('Action','İşlem'),t('Resource','Kaynak'),t('Result','Sonuç'),''],events.map(e=>`<tr><td>${e.time}<p class="mono">#${e.id}</p></td><td><div class="flex"><span class="avatar" style="width:25px;height:25px;font-size:9px">${e.actor==='System'?icon('Settings2'):e.actor.split(' ').map(x=>x[0]).join('')}</span>${e.actor}</div></td><td class="mono" style="font-size:10px">${e.action}</td><td>${esc(e.object)}</td><td>${statusBadge(e.result)}</td><td>${btn(t('Details','Ayrıntılar'),'audit-detail','ChevronRight','ghost small',`data-id="${e.id}"`)}</td></tr>`),t('Audit events','Denetim olayları'))}
